// Cycling category card
(function() {
  const slides = document.querySelectorAll('.cat-slide');
  const dots   = document.querySelectorAll('.cat-dot');
  const btns   = document.querySelectorAll('#categoryFilters .filter-btn');
  // index 0 = "All Events" → show wedding (idx 0); others map 1→0, 2→1, 3→2
  const map = [0, 0, 1, 2];
  let current = 0;

  function goTo(slideIdx) {
    slides[current].classList.remove('active');
    dots[current].classList.remove('active');
    current = slideIdx;
    slides[current].classList.add('active');
    dots[current].classList.add('active');
  }

  // Auto-cycle every 3s
  let timer = setInterval(() => { goTo((current + 1) % slides.length); }, 3000);

  btns.forEach((btn, i) => {
    btn.addEventListener('click', () => {
      btns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      clearInterval(timer);
      goTo(map[i]);
      timer = setInterval(() => { goTo((current + 1) % slides.length); }, 3000);
    });
  });
})();

// Menu controls
(function() {
  const dropBtn = document.getElementById('dropdownBtn');
  const dropMenu = document.getElementById('dropdownMenu');
  const closeBtn = document.getElementById('menuCloseBtn');
  const backdrop = document.getElementById('navBackdrop');
  function open() { if (!dropMenu) return; dropMenu.classList.add('open'); if (dropBtn) { dropBtn.classList.add('active'); dropBtn.setAttribute('aria-expanded','true'); } }
  function close() { if (!dropMenu) return; dropMenu.classList.remove('open'); if (dropBtn) { dropBtn.classList.remove('active'); dropBtn.setAttribute('aria-expanded','false'); } }
  if (dropBtn) dropBtn.addEventListener('click', e => { e.stopPropagation(); dropMenu.classList.contains('open') ? close() : open(); });
  if (closeBtn) closeBtn.addEventListener('click', close);
  if (backdrop) backdrop.addEventListener('click', close);
  if (dropMenu) dropMenu.querySelectorAll('a').forEach(a => a.addEventListener('click', close));
  window.addEventListener('scroll', () => { if (window.scrollY > 20) close(); }, { passive: true });
})();

// Lightbox elements (declared first so gallery functions can reference them)
const lightbox = document.getElementById('lightbox');
const lbImg = document.getElementById('lbImg');
const lbClose = document.getElementById('lbClose');
const lbPrev = document.getElementById('lbPrev');
const lbNext = document.getElementById('lbNext');
let currentIdx = 0;
let activeImages = [];

// Filter buttons → open full-screen gallery page
const filterBtns = document.querySelectorAll('.filter-btn');
const categoryCards = document.querySelectorAll('.category-card');
const galleryPage = document.getElementById('galleryPage');
const galleryPageGrid = document.getElementById('galleryPageGrid');
const galleryPageTitle = document.getElementById('galleryPageTitle');
const galleryPageClose = document.getElementById('galleryPageClose');
const dataPool = document.querySelectorAll('#galleryDataPool [data-cat]');

let gpImages = [];

function openGalleryLightbox(idx) {
  activeImages = gpImages;
  currentIdx = idx;
  lbImg.src = activeImages[idx];
  lightbox.classList.add('open');
}

function openGalleryPage(filter, label) {
  filterBtns.forEach(b => b.classList.toggle('active', b.dataset.filter === filter));
  const items = Array.from(dataPool).filter(i => filter === 'all' || i.dataset.cat === filter);
  gpImages = items.map(i => i.dataset.src);

  galleryPageTitle.textContent = label;
  galleryPageGrid.innerHTML = '';
  items.forEach((item, idx) => {
    const img = document.createElement('img');
    img.src = item.dataset.src;
    img.loading = 'lazy';
    img.style.cssText = 'width:100%;aspect-ratio:1;object-fit:cover;display:block;cursor:pointer;transition:transform 0.3s;';
    img.addEventListener('mouseenter', () => img.style.transform = 'scale(1.03)');
    img.addEventListener('mouseleave', () => img.style.transform = '');
    img.addEventListener('click', () => openGalleryLightbox(idx));
    galleryPageGrid.appendChild(img);
  });

  galleryPage.style.display = 'block';
  galleryPage.scrollTop = 0;
  document.body.style.overflow = 'hidden';
}

filterBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    openGalleryPage(btn.dataset.filter, btn.dataset.label || btn.textContent);
  });
});

// Editorial gallery preview — "View Full Gallery" link
[document.getElementById('galleryViewAllLink')].forEach(el => {
  if (!el) return;
  el.addEventListener('click', (e) => {
    e.preventDefault();
    openGalleryPage('all', 'All Events');
  });
});

galleryPageClose.addEventListener('click', () => {
  galleryPage.style.display = 'none';
  document.body.style.overflow = '';
});

// Category card click → open gallery page
categoryCards.forEach(card => {
  card.addEventListener('click', () => {
    const cat = card.dataset.category;
    const label = cat === 'wedding' ? 'Weddings' : cat === 'corporate' ? 'Corporate' : 'Live Events';
    openGalleryPage(cat, label);
  });
});

function closeLightbox() {
  lightbox.classList.remove('open');
  document.body.style.overflow = galleryPage.style.display === 'block' ? 'hidden' : '';
}

lbClose.addEventListener('click', closeLightbox);
lightbox.addEventListener('click', e => { if (e.target === lightbox) closeLightbox(); });

lbPrev.addEventListener('click', () => {
  currentIdx = (currentIdx - 1 + activeImages.length) % activeImages.length;
  lbImg.src = activeImages[currentIdx];
});
lbNext.addEventListener('click', () => {
  currentIdx = (currentIdx + 1) % activeImages.length;
  lbImg.src = activeImages[currentIdx];
});
document.addEventListener('keydown', e => {
  if (!lightbox.classList.contains('open')) return;
  if (e.key === 'Escape') closeLightbox();
  if (e.key === 'ArrowLeft') lbPrev.click();
  if (e.key === 'ArrowRight') lbNext.click();
});

// Hero scroll cue (star) — mobile only. Hides once the page scrolls past
// the hero, reappears when scrolled back near the top. Gated to the
// ≤430px breakpoint so the desktop pulsing-line cue is left untouched.
(function() {
  const cue = document.querySelector('.events-hero__scroll');
  if (!cue) return;
  const mq = window.matchMedia('(max-width: 430px)');
  const onScroll = () => {
    if (!mq.matches) { cue.style.opacity = ''; return; }
    cue.style.opacity = window.scrollY > 40 ? '0' : '';
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  mq.addEventListener('change', onScroll);
  onScroll();
})();

// Scroll reveal
const reveals = document.querySelectorAll('.reveal');
const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) {
      e.target.classList.add('visible');
      revealObserver.unobserve(e.target);
    }
  });
}, { threshold: 0.12 });
reveals.forEach(el => revealObserver.observe(el));
